1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import { createContext, useContext } from "react";
3	import { useLocation } from "react-router-dom";
4	import { useView } from "@/contexts/ViewContext";
5	import type { Memo } from "@/types/proto/api/v1/memo_service_pb";
6	import { MemoRelation_Type } from "@/types/proto/api/v1/memo_service_pb";
7	import type { User } from "@/types/proto/api/v1/user_service_pb";
8	import type { PreviewMediaItem } from "@/utils/media-item";
9	import { RELATIVE_TIME_THRESHOLD_MS } from "./constants";
10	
11	export interface MemoViewContextValue {
12	  memo: Memo;
13	  creator: User | undefined;
14	  currentUser: User | undefined;
15	  parentPage: string;
16	  cardWidth: number;
17	  isArchived: boolean;
18	  readonly: boolean;
19	  showBlurredContent: boolean;
20	  blurred: boolean;
21	  openEditor: () => void;
22	  toggleBlurVisibility: () => void;
23	  openPreview: (items: string | string[] | PreviewMediaItem[], index?: number) => void;
24	}
25	
26	export const MemoViewContext = createContext<MemoViewContextValue | null>(null);
27	
28	export const useMemoViewContext = (): MemoViewContextValue => {
29	  const context = useContext(MemoViewContext);
30	  if (!context) {
31	    throw new Error("useMemoViewContext must be used within MemoViewContext.Provider");
32	  }
33	  return context;
34	};
35	
36	export const computeCommentAmount = (memo: Memo): number =>
37	  memo.relations.filter((r) => r.type === MemoRelation_Type.COMMENT && r.relatedMemo?.name === memo.name).length;
38	
39	export const useMemoViewDerived = () => {
40	  const { memo, isArchived, readonly } = useMemoViewContext();
41	  const { timeBasis } = useView();
42	  const location = useLocation();
43	
44	  const isInMemoDetailPage = location.pathname.startsWith(`/${memo.name}`) || location.pathname.startsWith("/memos/shares/");
45	  const commentAmount = computeCommentAmount(memo);
46	
47	  const createTime = memo.createTime ? timestampDate(memo.createTime) : undefined;
48	  const updateTime = memo.updateTime ? timestampDate(memo.updateTime) : undefined;
49	  const displayTime = timeBasis === "update_time" ? updateTime : createTime;
50	  const isDisplayingUpdatedTime =
51	    timeBasis === "update_time" && !!createTime && !!updateTime && updateTime.getTime() !== createTime.getTime();
52	  const relativeTimeFormat: "datetime" | "auto" =
53	    displayTime && Date.now() - displayTime.getTime() > RELATIVE_TIME_THRESHOLD_MS ? "datetime" : "auto";
54	
55	  return {
56	    isArchived,
57	    readonly,
58	    isInMemoDetailPage,
59	    commentAmount,
60	    createTime,
61	    updateTime,
62	    displayTime,
63	    isDisplayingUpdatedTime,
64	    relativeTimeFormat,
65	  };
66	};
