1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import { separateAttachments } from "@/components/MemoMetadata/Attachment/attachmentHelpers";
3	import type { Memo } from "@/types/proto/api/v1/memo_service_pb";
4	import type { User } from "@/types/proto/api/v1/user_service_pb";
5	import { type AttachmentVisualItem, buildAttachmentVisualItems, countLogicalAttachmentItems } from "@/utils/media-item";
6	import { getMemoSharePreviewAvatarUrl } from "./memoShareImage";
7	
8	interface BuildMemoShareImagePreviewModelOptions {
9	  memo: Memo;
10	  creator?: User;
11	  fallbackDisplayName: string;
12	  locale: string;
13	}
14	
15	export interface MemoShareImageAttachmentSummaryBadge {
16	  type: "attachment-summary";
17	  count: number;
18	}
19	
20	export type MemoShareImageFooterBadge = MemoShareImageAttachmentSummaryBadge;
21	
22	export interface MemoShareImagePreviewModel {
23	  displayName: string;
24	  avatarUrl?: string;
25	  formattedDisplayTime?: string;
26	  visualItems: AttachmentVisualItem[];
27	  footerBadges: MemoShareImageFooterBadge[];
28	}
29	
30	export const buildMemoShareImagePreviewModel = ({
31	  memo,
32	  creator,
33	  fallbackDisplayName,
34	  locale,
35	}: BuildMemoShareImagePreviewModelOptions): MemoShareImagePreviewModel => {
36	  const displayName = creator?.displayName || creator?.username || fallbackDisplayName;
37	  const avatarUrl = getMemoSharePreviewAvatarUrl(creator?.avatarUrl);
38	  const displayTime = memo.createTime ? timestampDate(memo.createTime) : undefined;
39	  const formattedDisplayTime = displayTime?.toLocaleString(locale, {
40	    dateStyle: "medium",
41	    timeStyle: "short",
42	  });
43	
44	  const attachmentGroups = separateAttachments(memo.attachments);
45	  const visualItems = buildAttachmentVisualItems(attachmentGroups.visual);
46	  const attachmentCount = countLogicalAttachmentItems(memo.attachments);
47	  const nonVisualAttachmentCount = Math.max(attachmentCount - visualItems.length, 0);
48	  const footerBadges: MemoShareImageFooterBadge[] =
49	    nonVisualAttachmentCount > 0 ? [{ type: "attachment-summary", count: attachmentCount }] : [];
50	
51	  return {
52	    displayName,
53	    avatarUrl,
54	    formattedDisplayTime,
55	    visualItems,
56	    footerBadges,
57	  };
58	};
```

