1	import { ArrowUpRightIcon } from "lucide-react";
2	import { Link } from "react-router-dom";
3	import { MemoPreview } from "@/components/MemoPreview";
4	import { useMemoComments } from "@/hooks/useMemoQueries";
5	import { useUsersByNames } from "@/hooks/useUserQueries";
6	import { extractMemoIdFromName } from "@/lib/resource-names";
7	import { useMemoViewContext, useMemoViewDerived } from "../MemoViewContext";
8	
9	const MemoCommentListView: React.FC = () => {
10	  const { memo } = useMemoViewContext();
11	  const { isInMemoDetailPage, commentAmount } = useMemoViewDerived();
12	
13	  const { data } = useMemoComments(memo.name, { enabled: !isInMemoDetailPage && commentAmount > 0, pageSize: 3 });
14	  const comments = data?.memos ?? [];
15	  const displayedComments = comments.slice(0, 3);
16	  const { data: commentCreators } = useUsersByNames(displayedComments.map((comment) => comment.creator));
17	
18	  if (isInMemoDetailPage || commentAmount === 0) {
19	    return null;
20	  }
21	
22	  return (
23	    <div className="border border-t-0 border-border rounded-b-lg px-4 pt-2 pb-3 flex flex-col gap-1">
24	      <div className="flex items-center justify-between mb-1">
25	        <span className="text-xs text-muted-foreground">Comments{commentAmount > 1 ? ` (${commentAmount})` : ""}</span>
26	        <Link
27	          to={`/${memo.name}#comments`}
28	          className="flex items-center gap-0.5 text-xs text-muted-foreground/80 hover:underline underline-offset-2 transition-colors"
29	        >
30	          View all
31	          <ArrowUpRightIcon className="w-3 h-3" />
32	        </Link>
33	      </div>
34	      {displayedComments.map((comment) => {
35	        const uid = extractMemoIdFromName(comment.name);
36	        const creator = commentCreators?.get(comment.creator);
37	        return (
38	          <Link
39	            key={comment.name}
40	            to={`/${memo.name}#${uid}`}
41	            viewTransition
42	            className="rounded-md bg-muted/40 px-2 py-1 transition-colors hover:bg-muted/60"
43	          >
44	            <MemoPreview
45	              content={comment.snippet || comment.content}
46	              attachments={comment.attachments}
47	              creator={creator}
48	              showCreator
49	              truncate
50	            />
51	          </Link>
52	        );
53	      })}
54	    </div>
55	  );
56	};
57	
58	export default MemoCommentListView;
```

